class Tally:
    def __init__(self):
        self.count = 0

    def report_increment(self, n=1):
        self.count += n

    def report_decrement(self, n=1):
        self.count -= n

    def get_total(self):
        return self.count

    def merge(self, other):
        self.count += other.get_total()


# Provide a factory method if needed

def create():
    return Tally()

