from dataclasses import dataclass, field
from datetime import datetime, timedelta, time
from typing import List, Optional

@dataclass
class Booking:
    start_time: datetime
    end_time: datetime
    description: str
    recurrence_weekly: bool = False

    def occurs_on(self, date: datetime) -> bool:
        # Check if booking occurs on a specific date
        if self.recurrence_weekly:
            # Match day of week
            return self.start_time.weekday() == date.weekday()
        else:
            # Check exact date
            return self.start_time.date() == date.date()

class SlotBook:
    def __init__(self):
        self.bookings: List[Booking] = []

    def add_booking(self, start_time: datetime, end_time: datetime, description: str, recurrence_weekly: bool = False):
        self.bookings.append(Booking(start_time, end_time, description, recurrence_weekly))

    def get_bookings_for_day(self, date: datetime) -> List[Booking]:
        return [b for b in self.bookings if b.occurs_on(date)]

